// Joint plan (pulse microseconds; tighten these to YOUR arm)
// 0 base:     min 600  max 2400  home 1500
// 1 shoulder: min 900  max 2100  home 1500
// 2 elbow:    min 700  max 2300  home 1500
// 3 gripper:  open 1900  closed 1200

#include <Servo.h>
Servo joints[4];
const int PIN[4] = {3, 5, 6, 9};
int jmin[4] = {600, 900, 700, 1200};
int jmax[4] = {2400, 2100, 2300, 1900};

void setupArm() {
  for (int i = 0; i < 4; i++) joints[i].attach(PIN[i]);
}

void setJoint(int i, int us) {
  us = constrain(us, jmin[i], jmax[i]);   // never exceed a joint's limit
  joints[i].writeMicroseconds(us);
}

int home_us[4] = {1500, 1500, 1500, 1700};

void home() {
  for (int i = 0; i < 4; i++) setJoint(i, home_us[i]);
}

int cur[4] = {1500, 1500, 1500, 1700};

void moveJoint(int i, int target, int stepMs) {
  target = constrain(target, jmin[i], jmax[i]);
  int dir = target > cur[i] ? 1 : -1;
  while (cur[i] != target) {
    cur[i] += dir * min(5, abs(target - cur[i]));  // 5us per step
    setJoint(i, cur[i]);
    delay(stepMs);                                 // pace the ramp
  }
}

void moveTo(int t[4], int stepMs) {
  bool moving = true;
  while (moving) {
    moving = false;
    for (int i = 0; i < 4; i++) {
      int tgt = constrain(t[i], jmin[i], jmax[i]);
      if (cur[i] != tgt) {
        cur[i] += (tgt > cur[i] ? 1 : -1) * min(5, abs(tgt - cur[i]));
        setJoint(i, cur[i]);
        moving = true;
      }
    }
    delay(stepMs);
  }
}

int sel = 0;   // selected joint

void handleSerial() {
  if (!Serial.available()) return;
  char c = Serial.read();
  if (c >= '0' && c <= '3') sel = c - '0';
  else if (c == '+') moveJoint(sel, cur[sel] + 25, 8);
  else if (c == '-') moveJoint(sel, cur[sel] - 25, 8);
  else if (c == 'p') { for (int i=0;i<4;i++){Serial.print(cur[i]);Serial.print(' ');} Serial.println(); }
}

// Poses captured from teach mode {base, shoulder, elbow, gripper}
int POSE_HOME[4]    = {1500, 1500, 1500, 1900};  // gripper open
int POSE_OVER_PICK[4]= {1700, 1400, 1600, 1900};
int POSE_PICK[4]    = {1700, 1650, 1750, 1900};
int POSE_PLACE[4]   = {1250, 1650, 1750, 1200};  // gripper closed

const int GRIP = 3;
void gripOpen()  { moveJoint(GRIP, 1900, 6); }
void gripClose() { moveJoint(GRIP, 1200, 6); }

#include <math.h>
const float L1 = 10.5, L2 = 9.0;   // cm, measure your arm

bool ik2(float x, float y, float &shoulder, float &elbow) {
  float r2 = x*x + y*y;
  float c2 = (r2 - L1*L1 - L2*L2) / (2*L1*L2);
  if (c2 < -1 || c2 > 1) return false;      // out of reach
  elbow = acos(c2);                          // elbow-down solution
  shoulder = atan2(y, x) - atan2(L2*sin(elbow), L1 + L2*cos(elbow));
  return true;
}

// angle (radians) -> pulse for a joint, using measured offset & scale
int angleToUs(int joint, float radians) {
  float deg = radians * 180.0 / PI;
  // tune OFFSET_DEG[] and US_PER_DEG[] per joint by calibration
  extern float OFFSET_DEG[4], US_PER_DEG[4];
  return (int)(1500 + (deg - OFFSET_DEG[joint]) * US_PER_DEG[joint]);
}

void pickAndPlace() {
  home();          gripOpen();
  moveTo(POSE_OVER_PICK, 8);
  moveTo(POSE_PICK, 10);
  gripClose();     delay(300);      // let the grip settle
  moveTo(POSE_OVER_PICK, 8);        // lift straight up
  moveTo(POSE_PLACE, 8);
  gripOpen();      delay(300);
  home();
}
